+/** Splits CSV text into rows of fields, honoring quoted fields. */
+function parseCsv(text) {
+  const rows = [];
+  let row = [];
+  let field = "";
+  let quoted = false;
+  for (let i = 0; i < text.length; i++) {
+    const c = text[i];
+    if (quoted) {
+      if (c === '"' && text[i + 1] === '"') {
+        field += '"';
+        i++;
+      } else if (c === '"') quoted = false;
+      else field += c;
+    } else if (c === '"') quoted = true;
+    else if (c === ",") {
+      row.push(field);
+      field = "";
+    } else if (c === "\n" || c === "\r") {
+      if (c === "\r" && text[i + 1] === "\n") i++;
+      row.push(field);
+      rows.push(row);
+      row = [];
+      field = "";
+    } else field += c;
+  }
+  if (field !== "" || row.length) {
+    row.push(field);
+    rows.push(row);
+  }
+  return rows;
+}
+
+/** Reads data/stock.csv into objects with sku, name, qty, unit and shelf. */
+async function readStock() {
+  const [, ...rows] = parseCsv(await readFile(STOCK_FILE, "utf8"));
+  return rows
+    .filter((r) => r.some((f) => f !== ""))
+    .map(([sku, name, qty, unit, shelf]) => ({
+      sku,
+      name,
+      qty: Number(qty),
+      unit: unit === "" ? null : unit,
+      shelf,
+    }));
+}

